// Logo embedded (flattened onto white) so PDFs never depend on loading an image file
const LOGO_DATA = 'data:image/png;base64,';
const LOGO_RATIO = 0.33286;

// Brand assets for the web app (transparent logo for the header and login, icon for the browser tab)
const LOGO_WEB = 'data:image/png;base64,';
const LOGO_ICON = 'data:image/png;base64,';
document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('img.brand-logo').forEach(i => { i.src = LOGO_WEB; });
    const l = document.createElement('link');
    l.rel = 'icon'; l.href = LOGO_ICON;
    document.head.appendChild(l);
});